/**
 * Local integration test: validates pricing calculations against real extracted data.
 *
 * Reads items_enriched.json + pricing.csv + rules.csv (generated by generate_tables.py)
 * and runs ItemLogic + RulesCoordinator from dev/src against real catalog items.
 *
 * Run: node test_pricing.mjs
 */

import { readFileSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dir = dirname(fileURLToPath(import.meta.url));
const devSrc = resolve(__dir, '../dev/src/services/pricing/item');

// ── Inline CSV parser (no dependencies) ─────────────────────────────────────

function parseCsv(content) {
  const lines = content.replace(/\r\n/g, '\n').split('\n').filter(l => l.trim());
  if (!lines.length) return [];
  const headers = splitCsvLine(lines[0]);
  return lines.slice(1).map(line => {
    const vals = splitCsvLine(line);
    const row = {};
    headers.forEach((h, i) => { row[h] = vals[i] ?? ''; });
    return row;
  });
}

function splitCsvLine(line) {
  const cells = [];
  let cur = '';
  let inQ = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (ch === '"') {
      if (inQ && line[i + 1] === '"') { cur += '"'; i++; }
      else inQ = !inQ;
    } else if (ch === ',' && !inQ) {
      cells.push(cur.trim()); cur = '';
    } else {
      cur += ch;
    }
  }
  cells.push(cur.trim());
  return cells;
}

// ── Load generated data ──────────────────────────────────────────────────────

const items   = JSON.parse(readFileSync(resolve(__dir, 'processed_data/items_enriched.json'), 'utf8'));
const pricing = parseCsv(readFileSync(resolve(__dir, 'processed_data/pricing.csv'), 'utf8'));
const rules   = parseCsv(readFileSync(resolve(__dir, 'processed_data/rules.csv'), 'utf8'));

// Index by id
const pricingById = Object.fromEntries(pricing.map(p => [p.pricing_id, p]));
const rulesById   = Object.fromEntries(rules.map(r => [r.rule_id, r]));
const itemsById   = {};
for (const item of items) {
  itemsById[`${item.item_id}__${item.year}`] = item;
}

// ── Pricing profile mapper ───────────────────────────────────────────────────
// Maps our extracted pricing row → pricingProfile understood by ItemLogic/normalizeProfile.
// - per_person OR base_plus_variable → Costo_Unitario_Pax
// - per_unit                         → Costo_Unitario_Item
// - flat                             → Costo_Base_Fijo only

function toPricingProfile(pricingRow) {
  if (!pricingRow) return { Costo_Base_Fijo: 0, Costo_Unitario_Pax: 0, Costo_Unitario_Item: 0, Costo_Unitario_Tiempo: 0 };
  const base     = parseFloat(pricingRow.base_value)     || 0;
  const variable = parseFloat(pricingRow.variable_value) || 0;
  const expr     = pricingRow.expression_type;
  return {
    Costo_Base_Fijo:       base,
    Costo_Unitario_Pax:    (expr === 'per_person' || expr === 'base_plus_variable') ? variable : 0,
    Costo_Unitario_Item:   expr === 'per_unit' ? variable : 0,
    Costo_Unitario_Tiempo: 0,
  };
}

// ── Rule mapper ──────────────────────────────────────────────────────────────
// ItemLogic.recalculate() calls evaluateRules() from Formulas.js, which uses a
// simple format: { type: 'MAX_PAX'|'MIN_PAX'|'ONLY_HOUR_RANGE', value, active, blocking }.
// (RulesCoordinator uses JSON-Logic, but it's not wired into ItemLogic yet.)

function toItemLogicRules(ruleRow) {
  const min = ruleRow.hint_min !== '' ? parseFloat(ruleRow.hint_min) : null;
  const max = ruleRow.hint_max !== '' ? parseFloat(ruleRow.hint_max) : null;
  const unit = ruleRow.hint_unit || '';
  if (unit !== 'pax') return []; // only pax-capacity rules supported by evaluateRules

  const blocking = ruleRow.rule_type === 'capacity';
  const out = [];
  if (min !== null) out.push({ id: ruleRow.rule_id + '_min', type: 'MIN_PAX', value: min, label: ruleRow.raw_text, active: true, blocking });
  if (max !== null) out.push({ id: ruleRow.rule_id + '_max', type: 'MAX_PAX', value: max, label: ruleRow.raw_text, active: true, blocking });
  return out;
}

// ── Import dev pricing engine ────────────────────────────────────────────────

const { ItemLogic } = await import(`${devSrc}/ItemLogic.js`);

// ── Test harness ─────────────────────────────────────────────────────────────

let passed = 0;
let failed = 0;

function assert(label, condition, detail = '') {
  if (condition) {
    console.log(`  ✓ ${label}`);
    passed++;
  } else {
    console.log(`  ✗ ${label}${detail ? ': ' + detail : ''}`);
    failed++;
  }
}

function testItem(itemKey, testPax, expectedTotal, expectBlocked = false) {
  const item = itemsById[itemKey];
  if (!item) { console.log(`  ✗ Item not found: ${itemKey}`); failed++; return; }

  const pricingRow = item.pricing_ids[0] ? pricingById[item.pricing_ids[0]] : null;
  const profile = toPricingProfile(pricingRow);

  const ruleObjects = item.rule_ids.flatMap(rid => toItemLogicRules(rulesById[rid] || {}));

  const logic = new ItemLogic({
    mode: 'basket',
    definition: { pricingProfile: profile, rules: ruleObjects },
    externalContext: { paxGlobal: testPax },
    overrides: { pax: testPax },
  });

  const raw = item.raw || {};
  const rawVals = Object.values(raw);
  const rawName = rawVals[0] || item.item_id;

  console.log(`\n── ${item.item_id} (${item.year}) ──`);
  console.log(`   raw: "${rawName.substring(0, 60)}..."`);
  console.log(`   expression: ${pricingRow?.expression_type || 'none'}  base=${profile.Costo_Base_Fijo}  pax_rate=${profile.Costo_Unitario_Pax}  unit_rate=${profile.Costo_Unitario_Item}`);
  console.log(`   test pax=${testPax}  expected=${expectedTotal}  got=${logic.total}`);

  assert(`total matches for pax=${testPax}`, logic.total === expectedTotal, `got ${logic.total}`);
  assert(`available = ${!expectBlocked}`, logic.available === !expectBlocked, `got ${logic.available}`);
  console.log(`   basket legend: ${logic.basketLegendText}`);
}

// ── Test cases (item_id__year, pax, expectedTotal, expectBlocked) ────────────

console.log('\n══════════════════════════════════════════');
console.log(' Pricing integration test — real catalog  ');
console.log('══════════════════════════════════════════\n');

// 1. FLAT pricing — Salon Chinook: 385000 fixed, no pax component
testItem('SALON_CHINOOK_USO_DIURNO__2025', 50, 385000, false);

// 2. PER_PERSON — Desayuno: 12500/pax
testItem('DESAYUNO__2025', 20, 20 * 12500, false);

// 3. PER_PERSON — Coffee Básico: 6380/pax
testItem('COFFEE_BASICO__2025', 30, 30 * 6380, false);

// 4. BASE_PLUS_VARIABLE — Cata de vinos: 300000 + 24000/pax
//    min=10 max=40 pax rule → blocked at pax=5
testItem('CATA_VINOS__2025', 15, 300000 + 15 * 24000, false);
testItem('CATA_VINOS__2025', 5, 300000 + 5 * 24000, true);  // blocked: < 10 pax

// 5. PER_PERSON — Once: 9800/pax
testItem('ONCE__2025', 10, 10 * 9800, false);

// 6. FLAT — Cambio montaje Chinook: 150000 fixed
testItem('CAMBIO_MONTAJE_CHINOOK__2025', 1, 150000, false);

// 7. Year comparison — Almuerzo Buffet 2025 vs 2026 prices
{
  const item25 = itemsById['ALMUERZO_BUFFET__2025'];
  const item26 = itemsById['ALMUERZO_BUFFET__2026'];
  const p25 = item25?.pricing_ids[0] ? pricingById[item25.pricing_ids[0]] : null;
  const p26 = item26?.pricing_ids[0] ? pricingById[item26.pricing_ids[0]] : null;
  const rate25 = parseFloat(p25?.variable_value || 0);
  const rate26 = parseFloat(p26?.variable_value || 0);
  console.log('\n── Year-over-year comparison: ALMUERZO_BUFFET ──');
  console.log(`   2025 rate: ${rate25.toFixed(2)} CLP/pax`);
  console.log(`   2026 rate: ${rate26.toFixed(2)} CLP/pax`);
  assert('2026 price is higher than 2025', rate26 > rate25, `${rate26} vs ${rate25}`);
}

// ── Summary ───────────────────────────────────────────────────────────────────

console.log('\n══════════════════════════════════════════');
console.log(` Results: ${passed} passed, ${failed} failed`);
console.log('══════════════════════════════════════════\n');
if (failed > 0) process.exit(1);
